import React, { Component } from 'react'
import Form from 'react-bootstrap/Form'
import DataTable from 'react-data-table-component'
import moment from 'moment'

class MessagesTable extends Component {


    handleChange = (event) => {
      
          this.props.handleMessagesSelectedRowsChange(event.selectedRows);
    }
    
    
    render() {
        
        console.log(this.props.messageType)
        if (this.props.messageType === 'sent') {
            console.log('yes')
               let showMessagesTable = this.props.showSentMessagesTable ? {display: 'block'} : {display: 'none'};
        } else if (this.props.messageType === 'received') {
               let showMessagesTable = this.props.showReceivedMessagesTable ? {display: 'block'} : {display: 'none'};
        } 
     
     console.log(showMessagesTable)
        const columns =  [
            { name: 'Recipient', selector: 'profileName', sortable: true },
            { name: 'Date', selector: 'createdAt', sortable: true, format: row => moment(row.createdAt).format('LLL')},
            { name: 'Message', selector: 'message', sortable: true, wrap: true }
            ];
               
        return (
          
          <Form className="messagesDataTable">
              <DataTable
                columns={columns}
                data={this.props.messageData} //needs to be dynamic
                defaultSortField="createdAt"
                defaultSortAsc="false"
                sortServer="true"
                selectableRows
                onSelectedRowsChange={this.handleChange}
                highlightOnHover
                clearSelectedRows={this.props.toggledClearRows}
                pagination
                paginationPerPage={10}
              />
                       
          </Form>
        )
    }

}

export default MessagesTable;
